      const re = /\b[a-zA-Z0-9_%+-]+(?:\s*\.\s*[a-zA-Z0-9_%+-]+)*(?:\s*@\s*|\s*\(\s*[aA][tT]\s*\)\s*|\s*\[\s*[aA][tT]\s*\]\s*|\s+[aA][tT]\s+)[a-zA-Z0-9-]+(?:\s*\.(?!\s*[A-Z])\s*[a-zA-Z0-9-]+)+\b/g;
